  rcvbl_db_int decimal(21,2) DEFAULT 0,
  urge_collt_db_int decimal(21,2) DEFAULT 0,
  rcvbl_acd_pnly_int decimal(21,2) DEFAULT 0,
  rcvbl_acd_pnly_int_occr_amt decimal(21,2) DEFAULT 0,
  urge_collt_acd_pnly_int decimal(21,2) DEFAULT 0,
  urge_acd_pnly_int_occr decimal(21,2) DEFAULT 0,
  rcvbl_pnly_int decimal(21,2) DEFAULT 0,
  urge_collt_pnly_int decimal(21,2) DEFAULT 0,
  acd_cmpd_int decimal(21,2) DEFAULT 0,
  acd_cmpd_int_occr_amt decimal(21,2) DEFAULT 0,
  acd_subsd_int decimal(21,2) DEFAULT 0,
